export const migrations = [
  {
    version: 1,
    up: 'CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, request_key TEXT UNIQUE NOT NULL, sku TEXT NOT NULL REFERENCES products(sku), quantity INTEGER NOT NULL, total_cents INTEGER NOT NULL)',
    down: 'DROP TABLE orders'
  },
  {
    version: 2,
    up: 'CREATE TABLE order_outbox (order_id INTEGER UNIQUE NOT NULL REFERENCES orders(id), event TEXT NOT NULL)',
    down: 'DROP TABLE order_outbox'
  }
];

export function seed(db) {
  db.exec('PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 5000');
  db.exec('CREATE TABLE products (sku TEXT PRIMARY KEY, name TEXT NOT NULL, price_cents INTEGER NOT NULL, stock INTEGER NOT NULL CHECK(stock >= 0))');
  const insert = db.prepare('INSERT INTO products VALUES (?, ?, ?, ?)');
  insert.run('coffee', 'Cà phê ☕', 1250, 10);
  insert.run('tea', 'Trà xanh', 900, 5);
}

export function migrate(db, migrations, targetVersion) {
  throw new Error('TODO transactional migration');
}

import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';
import { migrate } from '../src/migrations.mjs';
import { migrations, seed } from '../src/schema.mjs';

test('migration retries preserve rows across close/reopen and downgrade', async (t) => {
  const directory = await mkdtemp(join(tmpdir(), 'galaxy-ledger-'));
  t.after(() => rm(directory, { recursive: true, force: true }));
  const path = join(directory, 'ledger.sqlite');
  let db = new DatabaseSync(path);
  try {
    seed(db);
    assert.equal(migrate(db, migrations, 2), 2);
    assert.equal(migrate(db, migrations, 2), 2);
    assert.equal(db.prepare('SELECT count(*) AS n FROM schema_migrations').get().n, 2);
    assert.equal(db.prepare('SELECT name FROM products WHERE sku = ?').get('coffee').name, 'Cà phê ☕');
    db.close();
    db = new DatabaseSync(path);
    assert.equal(migrate(db, migrations, 1), 1);
    assert.equal(db.prepare("SELECT count(*) AS n FROM sqlite_master WHERE name = 'order_outbox'").get().n, 0);
    assert.equal(db.prepare("SELECT count(*) AS n FROM products").get().n, 2);
    assert.equal(migrate(db, migrations, 2), 2);
  } finally { db.close(); }
});

test('a later SQL failure rolls the whole upgrade back and allows a clean retry', () => {
  const db = new DatabaseSync(':memory:');
  try {
    seed(db);
    const broken = [migrations[0], { ...migrations[1], up: migrations[1].up + '; INSERT INTO missing_table VALUES (1)' }];
    assert.throws(() => migrate(db, broken, 2));
    assert.equal(db.prepare("SELECT count(*) AS n FROM sqlite_master WHERE name IN ('orders', 'order_outbox')").get().n, 0);
    const ledger = db.prepare("SELECT count(*) AS n FROM sqlite_master WHERE name = 'schema_migrations'").get().n;
    if (ledger) assert.equal(db.prepare('SELECT count(*) AS n FROM schema_migrations').get().n, 0);
    assert.equal(db.prepare('SELECT stock FROM products WHERE sku = ?').get('coffee').stock, 10);
    assert.equal(migrate(db, migrations, 2), 2);
    assert.throws(() => migrate(db, migrations, 99), /target|version/i);
    assert.equal(db.prepare('SELECT count(*) AS n FROM schema_migrations').get().n, 2);
  } finally { db.close(); }
});
